nebula_grade.fragment:
vec4 unoneShade(vec2 uv, vec4 color) {
 float dust = 0.5 + 0.5 * sin(uv.x * 16.0 + uv.y * 7.0 + unone_time * 0.12);
 float edge = smoothstep(0.12, 0.72, length((uv - vec2(0.5)) * vec2(0.85, 1.0)));
 vec3 graded = color.rgb * exposure * mix(vec3(0.90, 1.04, 1.10), sectorTint, 0.16);
 graded += color.rgb * dust * 0.025;
 return vec4(graded * (1.0 - edge * 0.20), color.a);
}

player_hull.fragment:
vec4 unoneShade(vec2 uv, vec4 color) {
 float nearby = max(max(texture2D(unone_texture, uv + vec2(0.004, 0.0)).a, texture2D(unone_texture, uv - vec2(0.004, 0.0)).a), max(texture2D(unone_texture, uv + vec2(0.0, 0.004)).a, texture2D(unone_texture, uv - vec2(0.0, 0.004)).a));
 float rim = max(0.0, nearby - color.a);
 float pulse = 0.80 + 0.20 * sin(unone_time * 3.0);
 vec3 lit = color.rgb * 1.30 + tint * (rim * strength * 1.7 * pulse + color.a * strength * 0.035);
 lit = mix(lit, vec3(2.3, 1.45, 0.65), min(1.0, impact) * 0.72);
 return vec4(lit, max(color.a, rim * strength * 0.65));
}

